pub fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // Empty prefix matches everything.
    if p.is_empty() {
        return true;
    }
    if v.len() < p.len() {
        return false;
    }

    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    true
}

pub fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered: Vec<Vec<char>> = Vec::new();

    for s in xs.into_iter() {
        if has_prefix(&s, &p) {
            filtered.push(s);
        }
    }

    filtered
}